"""Markdown exporter: human-readable handoff plus a paste-ready prompt."""

from __future__ import annotations

from pathlib import Path
from typing import Any, Mapping

from core.resume_engine import context_brief, continuation_prompt
from core.validator import validate_document


def render_markdown(document: Mapping[str, Any], destination: str = "Other") -> str:
    project = document.get("project") or {}
    title = str(project.get("name") or "Smart Capsule handoff")
    return (
        f"# {title}\n\n"
        "> Generated by Smart Capsule. Structured context only — no hidden model memory, "
        "account state or credentials are included.\n\n"
        f"{context_brief(document)}\n\n"
        "---\n\n"
        "## Continuation prompt (paste into a new chat)\n\n"
        "```text\n"
        f"{continuation_prompt(document, destination)}"
        "```\n"
    )


def export_markdown(document: Mapping[str, Any], target: Path, destination: str = "Other") -> Path:
    validate_document(document).raise_if_invalid()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(render_markdown(document, destination), encoding="utf-8", newline="\n")
    return target
